pub fn all_characters_same(s: &[u8]) -> bool {
    // If the slice has length 0 or 1, there is no pair of distinct indices
    // to compare, so by definition all characters are the same.
    if let Some((&first, rest)) = s.split_first() {
        // Check that every element in rest equals the first element
        rest.iter().all(|&b| b == first)
    } else {
        true
    }
}

